		"autoprefixer": "^10.4.23",
		"bits-ui": "^2.15.4",
		"clsx": "^2.1.1",
		"postcss": "^8.5.6",
		"svelte": "^5.45.6",
		"svelte-check": "^4.3.4",
		"tailwind-merge": "^3.4.0",
		"tailwind-variants": "^3.2.2",
		"tailwindcss": "^4.1.18",
